{"variables":{"urlPath":"/brand","type":"PAGEVIEW"},"query":"mutation ($type: GebEventType!, $productId: ProductIdInput, $comparisonId: LongInt, $shopStoreId: ShopStoreId, $searchKeyword: String, $urlPath: String) {
  gebTriggerEvent(
    type: $type
    productId: $productId
    comparisonId: $comparisonId
    shopStoreId: $shopStoreId
    searchKeyword: $searchKeyword
    urlPath: $urlPath
  ) {
    result
    matchedEvents {
      eventId
      eventTitle
      maxCountPerUser
      descriptionUrl
      endTime
      __typename
    }
    __typename
  }
}"}

{"variables":{"titleBarMaxKeywordCount":30},"query":"query ($titleBarMaxKeywordCount: Int!) {
  searchHotKeywords(pageSize: $titleBarMaxKeywordCount) {
    contents {
      keyword
      __typename
    }
    __typename
  }
  predefinedHotKeywords {
    value
    tag
    location
    imageUrl
    merchantId
    __typename
  }
}"}

{"variables":{},"query":"{
